-- Final counts should match the --mods and --events inputs.
SELECT COUNT(*) AS mod_count FROM mod_packages;
SELECT COUNT(*) AS download_count FROM mod_download_events;
SELECT COUNT(*) AS outbox_count FROM mod_download_outbox;
SELECT COUNT(*) AS missing_outbox FROM mod_download_events e LEFT JOIN mod_download_outbox o ON o.download_event_id=e.id WHERE o.id IS NULL;
SELECT mod_id, COUNT(*) AS downloads FROM mod_download_events GROUP BY mod_id ORDER BY downloads DESC LIMIT 10;
